import path from "node:path";

export const LOOPCOMPASS_SOURCE = "https://github.com/adammmmmm/LoopCompass";

function assertPortableManifestPath(relative) {
  if (
    !/^[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._-]+)*$/.test(relative) ||
    relative.split("/").some((segment) => segment === "." || segment === "..")
  ) {
    throw new Error("manifest file path is not portable");
  }
}

export function buildCanonicalManifest({
  version,
  commit,
  policyVersion,
  files,
}) {
  const lines = [
    "# Generated by scripts/release.mjs. Do not hand-edit digests.",
    "# Re-run: node scripts/release.mjs generate",
    "name: loop-compass",
    `version: ${version}`,
    `source: ${LOOPCOMPASS_SOURCE}`,
    `release: ${LOOPCOMPASS_SOURCE}/releases/tag/v${version}`,
    `commit: ${commit}`,
    "skill_schema: 1",
    `policy_version: ${policyVersion}`,
    "state_schema: 1",
    `minimum_policy_version: ${policyVersion}`,
    "files:",
  ];
  for (const relative of Object.keys(files).sort()) {
    assertPortableManifestPath(relative);
    if (!/^[0-9a-f]{64}$/.test(files[relative])) {
      throw new Error("manifest file digest is not canonical");
    }
    lines.push(`  ${relative}: ${files[relative]}`);
  }
  lines.push("");
  return lines.join("\n");
}

export function parseCanonicalManifest(text) {
  if (text.includes("\r") || !text.endsWith("\n")) {
    throw new Error("manifest is not canonical LF text");
  }
  const lines = text.slice(0, -1).split("\n");
  if (
    lines.length < 13 ||
    lines[0] !== "# Generated by scripts/release.mjs. Do not hand-edit digests." ||
    lines[1] !== "# Re-run: node scripts/release.mjs generate" ||
    lines[2] !== "name: loop-compass" ||
    lines[11] !== "files:"
  ) {
    throw new Error("manifest header is not canonical");
  }
  const value = (index, key) => {
    const prefix = `${key}: `;
    if (!lines[index]?.startsWith(prefix)) throw new Error("manifest field order");
    return lines[index].slice(prefix.length);
  };
  const version = value(3, "version");
  const source = value(4, "source");
  const release = value(5, "release");
  const commit = value(6, "commit");
  const skillSchema = value(7, "skill_schema");
  const policyVersion = value(8, "policy_version");
  const stateSchema = value(9, "state_schema");
  const minimumPolicyVersion = value(10, "minimum_policy_version");
  if (
    !/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/.test(version) ||
    source !== LOOPCOMPASS_SOURCE ||
    release !== `${LOOPCOMPASS_SOURCE}/releases/tag/v${version}` ||
    !/^(?:[0-9a-f]{40,64}|unknown)$/.test(commit) ||
    skillSchema !== "1" ||
    stateSchema !== "1" ||
    !/^\d+$/.test(policyVersion) ||
    minimumPolicyVersion !== policyVersion
  ) {
    throw new Error("manifest field value");
  }
  const files = {};
  for (const line of lines.slice(12)) {
    const match = line.match(/^  ([^:]+): ([0-9a-f]{64})$/);
    if (!match) throw new Error("manifest file entry");
    const relative = match[1].replaceAll("\\", "/");
    if (
      path.posix.isAbsolute(relative) ||
      relative.split("/").includes("..") ||
      Object.hasOwn(files, relative)
    ) {
      throw new Error("manifest file path");
    }
    assertPortableManifestPath(relative);
    files[relative] = match[2];
  }
  if (!Object.keys(files).length) throw new Error("manifest inventory is empty");
  const data = {
    name: "loop-compass",
    version,
    source,
    release,
    commit,
    skill_schema: skillSchema,
    policy_version: policyVersion,
    state_schema: stateSchema,
    minimum_policy_version: minimumPolicyVersion,
    files,
  };
  if (
    buildCanonicalManifest({
      version,
      commit,
      policyVersion: Number(policyVersion),
      files,
    }) !== text
  ) {
    throw new Error("manifest bytes are not canonical");
  }
  return data;
}
